<?php
require 'common.php';require_admin();$notice='';
if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$id=(string)($_POST['id']??'');$action=(string)($_POST['action']??'');$rows=products();foreach($rows as&$p){if(($p['id']??'')===$id){if($action==='publish')$p['status']='published';if($action==='draft')$p['status']='draft';if($action==='price')$p['price']=(float)($_POST['price']??0);$notice='تم تحديث المنتج.';audit('product_'.$action,$id);break;}}unset($p);save_json('products',$rows);}
$q=trim((string)($_GET['q']??''));$items=products();if($q!=='')$items=array_values(array_filter($items,fn($p)=>product_score($p,$q)>=45));admin_head('إدارة المنتجات');?>
<?php if($notice):?><div class="ok-box"><?=e($notice)?></div><?php endif;?>
<section class="panel"><div class="panel-head"><div><span>CATALOG OPERATIONS</span><h2>المنتجات</h2></div><form class="admin-search"><input name="q" value="<?=e($q)?>" placeholder="بحث بالموديل أو الاسم"><button>بحث</button></form></div><div class="table-wrap"><table class="products-table"><thead><tr><th>المنتج</th><th>الموديل</th><th>القسم</th><th>الجودة</th><th>الحالة</th><th>السعر</th><th>إجراء</th></tr></thead><tbody><?php foreach($items as$p):$quality=product_quality($p);?><tr><td><b><?=e((string)($p['name']??''))?></b><small><?=e((string)($p['brand']??''))?></small></td><td><?=e((string)($p['model']??'—'))?></td><td><?=e((string)($p['category']??'—'))?></td><td><span class="quality-chip <?=$quality>=80?'good':($quality>=60?'warn':'bad')?>"><?=$quality?>%</span></td><td><span class="status-pill <?=($p['status']??'draft')==='published'?'won':'review'?>"><?=($p['status']??'draft')==='published'?'منشور':'مسودة'?></span></td><td><?=!empty($p['price'])?money($p['price']):'—'?></td><td><form method="post" class="row-actions"><input type="hidden" name="csrf" value="<?=e(csrf_token())?>"><input type="hidden" name="id" value="<?=e((string)($p['id']??''))?>"><button name="action" value="<?=($p['status']??'draft')==='published'?'draft':'publish'?>"><?=($p['status']??'draft')==='published'?'إرجاع لمسودة':'نشر'?></button><a href="../product.php?slug=<?=urlencode((string)($p['slug']??''))?>" target="_blank">عرض ↗</a></form></td></tr><?php endforeach;?><?php if(!$items):?><tr><td colspan="7" class="muted-cell">لا توجد منتجات مطابقة.</td></tr><?php endif;?></tbody></table></div></section>
<?php admin_foot();?>